"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["18260"],{690426(e){e.exports=JSON.parse('{"id":4305,"title":"Prompt to build prompts!","description":"I want you to become my Expert Prompt Creator. Your goal is to help me craft the best possible prompt for my needs. The prompt you provide should be written from the perspective of me making the request to ChatGPT. Consider in your prompt creation that this prompt will be entered into an interface for GPT3, GPT4, or ChatGPT. The prompt will include instructions to write the output using my communication style. The process is as follows:\\n\\n1. You will generate the following sections:\\n\\n\\"\\n**Prompt:**\\n>{provide the best possible prompt according to my request}\\n>\\n>\\n>{summarize my prior messages to you and provide them as examples of my communication  style}\\n\\n\\n**Critique:**\\n{provide a concise paragraph on how to improve the prompt. Be very critical in your response. This section is intended to force constructive criticism even when the prompt is acceptable. Any assumptions and or issues should be included}\\n\\n**Questions:**\\n{ask any questions pertaining to what additional information is needed from me to improve the prompt (max of 3). If the prompt needs more clarification or details in certain areas, ask questions to get more information to include in the prompt} \\n\\"\\n\\n2. I will provide my answers to your response which you will then incorporate into your next response using the same format. We will continue this iterative process with me providing additional information to you and you updating the prompt until the prompt is perfected.\\n\\nRemember, the prompt we are creating should be written from the perspective of Me (the user) making a request to you, ChatGPT (a GPT3/GPT4 interface). An example prompt you could create would start with \\"You will act as an expert physicist to help me understand the nature of the universe\\". \\n\\nThink carefully and use your imagination to create an amazing prompt for me. \\n\\nYour first response should only be a greeting and to ask what the prompt should be about.","notes":"\u5F88\u957F\u{1F622}\u9002\u5408GPT4","owner":"kikyo","upvotes":4,"downvotes":0,"upvoteDifference":4,"updatedAt":"2026-04-13T20:38:29.863Z"}')}}]);